<style>
.eq-ui{--eq-main:var(--website-theme-main,#173247);--eq-sub:var(--website-theme-sub,#EF7B32);--eq-on-main:#fff;color:var(--eq-main);--eq-body-font:var(--lg-body-font,Arial,sans-serif);--eq-heading-font:var(--lg-heading-font,Arial,sans-serif)}.eq-site{padding:48px var(--storefront-content-gutter);background:color-mix(in srgb,var(--eq-main) 4%,white)}.eq-card{border-radius:5px;border-color:color-mix(in srgb,var(--eq-main) 18%,white);box-shadow:0 16px 60px #17324718}.eq-heading{border-top:4px solid var(--eq-sub)}.eq-ui h1{color:var(--eq-main);font-weight:800!important;letter-spacing:-.02em}.eq-ui .eq-product{border-radius:4px;background:color-mix(in srgb,var(--eq-main) 4%,white)}.eq-ui .eq-product img{object-fit:contain;background:white;border-radius:3px}.eq-ui .eq-product h2{color:var(--eq-main)}.eq-ui :is(input,textarea){border-radius:4px}.eq-ui :is(.eq-primary,.eq-secondary,.eq-cancel){border-radius:4px}.eq-success .eq-summary{border-radius:4px;border-color:color-mix(in srgb,var(--eq-main) 18%,white)}.eq-success .eq-tick{display:grid;place-items:center;width:48px;height:48px;border-radius:50%;background:var(--eq-main);color:white;margin-bottom:20px}.eq-reference{background:color-mix(in srgb,var(--eq-sub) 12%,white);color:var(--eq-main)}
@media(max-width:600px){.eq-site{padding-block:25px}.eq-success .eq-actions{flex-direction:column}.eq-success .eq-actions>*{width:100%}}
</style>
